shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const content = fs.readFileSync('src/orchestration/chatOrchestrator.test.ts', 'utf8');

const newTest = `
    it('called with wrapped Error when stream fails with a non-Error', async () => {
      let receivedError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          receivedError = error;
        },
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider('boom string' as any),
        promptBuilder,
        undefined,
        {hooks}
      );

      const thrown = await orchestrator.processMessage(createSession('hello')).catch(e => e);

      expect(thrown).toBe('boom string');
      expect(receivedError).toBeInstanceOf(Error);
      expect(receivedError?.message).toBe('boom string');
      expect(receivedError?.cause).toBe('boom string');
    });
`;

const lines = content.split('\n');
const insertIndex = lines.findIndex(l => l.includes("it('error still propagates after onError hook'"));
lines.splice(insertIndex, 0, newTest);

fs.writeFileSync('src/orchestration/chatOrchestrator.test.ts', lines.join('\n'));
EOF
node patch.js

node -e "
const reason = {code: 503, detail: 'upstream down'};
console.log(JSON.stringify(reason) || String(reason));
console.log(JSON.stringify(undefined) || String(undefined));
console.log(JSON.stringify(null) || String(null));
"
